<template><PageShell title="System Administration" subtitle="Monitor DASCARE availability, administrative accounts, security posture, and core configuration." icon="lucide:shield-check" eyebrow="Technical Super Admin"><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Stat label="Registered users" :value="stats.users_total" icon="lucide:users"/><Stat label="Active organizations" :value="stats.organizations_active" icon="lucide:building-2"/><Stat label="Active incidents" :value="stats.active_incidents" icon="lucide:siren"/><Stat label="Rate-limit alerts" :value="stats.rate_limit_alerts" icon="lucide:shield-alert"/></div><div class="mt-6 grid gap-6 xl:grid-cols-[.9fr_1.1fr]"><section class="rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm dark:border-white/10 dark:bg-[#071829]"><h2 class="text-lg font-black dark:text-white">Core health</h2><div class="mt-4 space-y-3"><Health label="API runtime" :ok="health.api"/><Health label="Database" :ok="health.database"/><Health label="Session service" :ok="health.session"/><Health label="Upload storage writable" :ok="health.storage_writable"/></div><div class="mt-5 rounded-2xl bg-base-200 p-4 text-xs text-slate-500"><p><strong>PHP:</strong> {{ health.php_version||'—' }}</p><p class="mt-1"><strong>Host:</strong> {{ health.environment||'—' }}</p></div></section><section class="rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm dark:border-white/10 dark:bg-[#071829]"><div class="flex justify-between"><div><h2 class="text-lg font-black dark:text-white">Recent system activity</h2><p class="mt-1 text-xs text-slate-400">Audit events from the current database.</p></div><RouterLink to="/system/logs" class="text-xs font-black text-red-600 no-underline">View all</RouterLink></div><div class="mt-4 divide-y divide-base-300 dark:divide-white/5"><article v-for="i in recent" :key="i.id" class="py-3"><p class="text-sm font-black text-slate-700 dark:text-white/70">{{ pretty(i.action) }}</p><p class="mt-1 text-xs text-slate-400">{{ i.actor_name||'System' }} · {{ format(i.created_at) }}</p></article><p v-if="!recent.length" class="py-10 text-center text-sm text-slate-400">No recent audit activity.</p></div></section></div></PageShell></template>
<script setup>import{defineComponent,h,onMounted,ref}from'vue';import{RouterLink}from'vue-router';import{Icon}from'@iconify/vue';import PageShell from '@/components/management/PageShell.vue';import{fetchTechnicalSummary}from'@/services/adminCompletion';const stats=ref({}),health=ref({}),recent=ref([]);const Stat=defineComponent({props:{label:String,value:[String,Number],icon:String},setup:p=>()=>h('article',{class:'rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm dark:border-white/10 dark:bg-[#071829]'},[h(Icon,{icon:p.icon,width:20,class:'text-red-500'}),h('p',{class:'mt-4 text-2xl font-black dark:text-white'},String(p.value??0)),h('p',{class:'mt-1 text-xs font-bold text-slate-500'},p.label)])});const Health=defineComponent({props:{label:String,ok:Boolean},setup:p=>()=>h('div',{class:'flex items-center justify-between rounded-2xl bg-base-200 p-3'},[h('span',{class:'text-sm font-bold text-slate-600 dark:text-white/60'},p.label),h('span',{class:['rounded-full px-2.5 py-1 text-[.65rem] font-black',p.ok?'bg-emerald-100 text-emerald-700':'bg-red-100 text-red-700']},p.ok?'Online':'Needs attention')])});const pretty=v=>String(v||'').replaceAll('.',' › ').replaceAll('_',' ');const format=v=>v?new Date(String(v).replace(' ','T')).toLocaleString():'—';onMounted(async()=>{const d=await fetchTechnicalSummary();stats.value=d.stats||{};health.value=d.health||{};recent.value=d.recent_activity||[]})</script>
